style.css:
/* === ANGEL PASTEL YOUTUBE THEME === */
/* Made for Stylus | Domain: youtube.com */

:root {
  --bg-main: #f4edf9;
  --bg-secondary: #ebe1f5;
  --accent: #c9b3e6;
  --accent-dark: #a78ed6;
  --text-main: #5a4a72;
  --text-soft: #8a7aa6;
}

/* Background */
body,
ytd-app {
  background-color: var(--bg-main) !important;
  color: var(--text-main) !important;
}
